'use strict';
// Presentation prototype. The adapter returns a fixed example, not a prediction.
const icons={sliders:'<path d="M4 6h5m5 0h6M4 12h10m5 0h1M4 18h1m5 0h10"/><circle cx="11" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="7" cy="18" r="2"/>',history:'<path d="M3 11a9 9 0 1 1 2.5 7M3 4v7h7M12 7v5l3 2"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M20 15.5A9 9 0 0 1 8.5 4 9 9 0 1 0 20 15.5Z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',bolt:'<path d="m13 2-9 12h7l-1 8L21 9h-8l1-7Z"/>',save:'<path d="M5 3h12l4 4v14H3V3h2Zm2 0v6h10V3M7 21v-7h10v7"/>'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const $=selector=>document.querySelector(selector);
const safe=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage={get(key,fallback){try{return JSON.parse(localStorage.getItem('casimir-'+key))??fallback}catch{return fallback}},set(key,value){try{localStorage.setItem('casimir-'+key,JSON.stringify(value))}catch{toast('Changes are available for this visit only.')}}};
const fields=[
 {key:'m',name:'Cathode coating mass',unit:'g',min:.010,max:.020,step:.0001,value:.015,decimals:4,help:'Dry coating applied to the cathode.'},
 {key:'f',name:'Active material fraction',unit:'fraction',min:.85,max:.95,step:.001,value:.90,decimals:3,help:'Share of the coating that stores charge.'},
 {key:'p',name:'Electrode porosity',unit:'fraction',min:.25,max:.45,step:.001,value:.35,decimals:3,help:'Open space within the electrode.'},
 {key:'c',name:'Compression ratio',unit:'fraction',min:.10,max:.30,step:.001,value:.20,decimals:3,help:'Thickness reduction during compression.'},
 {key:'e',name:'Electrolyte filling ratio',unit:'ratio',min:.80,max:1.20,step:.001,value:1.00,decimals:3,help:'Fill amount relative to the standard amount.'}
];
const defaults=()=>Object.fromEntries(fields.map(f=>[f.key,f.value]));
const storedHistory=storage.get('history',[]);
const state={route:'simulation',inputs:defaults(),result:null,running:false,error:'',customOpen:false,history:Array.isArray(storedHistory)?storedHistory.filter(r=>r&&r.inputs&&r.createdAt):[]};
const routes=[['simulation','bolt','Simulation'],['history','history','Saved results']];
// Replace this one boundary with the future tested backend. No calculation here.
const simulationAdapter={async initialize(inputs){await new Promise(resolve=>setTimeout(resolve,2200));return{capacity:1.840,reference:1.863,kind:'ui_fixture',inputs:{...inputs},createdAt:new Date().toISOString()}}};
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function setTheme(theme){document.documentElement.dataset.theme=theme;storage.set('theme',theme);const next=theme==='dark'?'light':'dark';$('#theme-toggle').innerHTML=icon(next==='light'?'sun':'moon',17);$('#theme-toggle').setAttribute('aria-label',`Switch to ${next} theme`);$('#theme-toggle').title=`Switch to ${next} theme`}
function heading(title,description){return `<div class="page-heading simple-heading"><div><span class="eyebrow">BATTERY PERFORMANCE, SIMPLIFIED</span><h1>${title}</h1><p>${description}</p></div><span class="badge quiet-badge">DESIGN PREVIEW</span></div>`}
function changed(){return fields.some(f=>Number(state.inputs[f.key])!==f.value)}
function fieldMarkup(f){return `<div class="field"><div class="field-title"><label for="input-${f.key}">${f.name}</label><span class="unit">${f.unit}</span></div><div class="input-row"><input type="range" id="range-${f.key}" aria-label="${f.name} slider" min="${f.min}" max="${f.max}" step="${f.step}" value="${state.inputs[f.key]}" data-field="${f.key}" aria-describedby="help-${f.key}"><input type="number" id="input-${f.key}" aria-label="${f.name} value" min="${f.min}" max="${f.max}" step="${f.step}" value="${state.inputs[f.key]===''?'':Number(state.inputs[f.key]).toFixed(f.decimals)}" required data-field="${f.key}" aria-describedby="help-${f.key}"></div><p class="field-help" id="help-${f.key}"><span>${f.help}</span><span>${f.min.toFixed(f.decimals)} – ${f.max.toFixed(f.decimals)}</span></p></div>`}
function simulation(){return `${heading('Your next simulation starts here.','Choose a setup, initialize, and let the app take care of the rest.')}
 <div class="simple-flow" aria-label="Your simulation steps"><span><b>01</b> Choose a setup</span><i></i><span><b>02</b> Initialize & wait</span><i></i><span><b>03</b> View your result</span></div>
 <div class="simulation-grid simple-grid"><section class="panel setup-panel"><div class="panel-heading"><h2>Your scenario</h2><span class="badge quiet-badge" id="scenario-badge">${changed()?'CUSTOM':'DEFAULT'}</span></div><p class="panel-subtitle">A ready-to-use setup. Change the values only if you need to.</p><div class="scenario-summary"><div class="scenario-art" aria-hidden="true"><div class="cell-art"><i></i><i></i><i></i></div></div><div><span class="eyebrow">${changed()?'YOUR SETUP':'READY TO BEGIN'}</span><h3 id="scenario-name">${changed()?'Custom cell scenario':'Default cell scenario'}</h3><p>Initial discharge capacity · mAh</p></div></div>
 <form id="simulation-form" novalidate><details id="customize" ${state.customOpen?'open':''}><summary>${icon('sliders',16)} Customize scenario <span>Optional <b>⌄</b></span></summary><div class="custom-fields"><p class="microcopy input-intro">Enter fractions, not percentages. For example, 0.90 means 90%.</p><fieldset id="scenario-fields" ${state.running?'disabled':''}>${fields.map(fieldMarkup).join('')}<button type="button" class="text-button" id="restore-defaults">Restore defaults ↺</button></fieldset></div></details><p class="error ${state.error?'':'hidden'}" id="form-error" role="alert">${safe(state.error)}</p><button type="submit" class="primary full initialize-button" id="initialize" ${state.running?'disabled':''}>${state.running?'<span class="button-spinner" aria-hidden="true"></span>':icon('bolt',17)} ${state.running?'Initializing simulation…':state.result?'Run another simulation':'Initialize simulation'} <span>${state.running?'':'→'}</span></button><p class="start-note">${icon('info',13)} ${state.running?'Please wait. Your result will appear automatically.':'One action starts the process. No extra setup required.'}</p></form></section>
 <section class="panel simple-result" aria-labelledby="result-title" aria-busy="${state.running}"><div id="result-content" aria-live="polite" aria-atomic="true">${resultMarkup()}</div></section></div>
 <div class="simple-bottom"><div>${icon('shield',17)}<p><strong>A simulation, clearly explained.</strong> Explore cell capacity in a controlled example.</p></div><button class="text-button" data-action="guide">First time here? Read the quick guide ↗</button></div><p class="prototype-note">Prototype review: the waiting state and result are examples. Entered values do not affect the displayed result yet.</p>`}
function resultMarkup(){if(state.running)return `<div class="result-top"><h2 id="result-title" tabindex="-1">Your result</h2><span class="badge quiet-badge">IN PROGRESS</span></div><div class="waiting-state"><div class="waiting-ring" aria-hidden="true"><span>${icon('bolt',29)}</span></div><h3>Initializing your simulation</h3><p>Sit back for a moment.<br>Your result will appear here when it’s ready.</p><div class="waiting-dots" aria-hidden="true"><i></i><i></i><i></i></div><small>Previewing the waiting experience</small></div>`;
 if(!state.result)return `<div class="result-top"><h2 id="result-title" tabindex="-1">Your result</h2><span class="result-status"><span class="status-dot"></span> Ready when you are</span></div><div class="ready-state"><div class="ready-symbol">${icon('bolt',33)}</div><h3>A little setup.<br>A clearer picture.</h3><p>Initialize your simulation to see a brief capacity summary and a simple explanation.</p><span class="ready-footnote">Your result will appear here automatically.</span></div>`;
 return `<div class="result-top"><h2 id="result-title" tabindex="-1">Your result</h2><span class="result-status">${icon('check',14)} Example ready</span></div><div class="completed-result"><p class="capacity-label">Initial discharge capacity</p><div class="capacity">1.840<small>mAh</small></div><span class="badge quiet-badge">ILLUSTRATIVE EXAMPLE</span><p class="result-explanation">This example represents <strong>1.840 milliampere-hours of charge</strong> delivered during an initial discharge. It shows how your simulation result will be explained.</p><button class="primary full" id="view-details">View more results ${icon('arrow',15)}</button><button class="secondary full save-result" id="save-scenario">${icon('save',15)} Save result</button><p class="result-note">Fixed example for interface review.</p></div>`}
function details(result){const isDefault=fields.every(f=>Number(result.inputs[f.key])===f.value);$('#details-dialog').innerHTML=`<div class="dialog-top"><span class="eyebrow">A CLOSER LOOK</span><button class="icon-button" data-close="details-dialog" aria-label="Close detailed results">×</button></div><h2 id="details-title">Your result, explained.</h2><p class="dialog-intro">Capacity describes how much charge a cell delivers. The example shown is <strong>1.840 mAh</strong>.</p><div class="notice"><strong>What this tells you</strong><p>This is an example of initial cell capacity. It does not describe battery lifetime or how long a solar installation will run.</p></div><h3>Scenario values</h3><div class="detail-values">${fields.map(f=>`<div><span>${f.name}</span><strong>${Number(result.inputs[f.key]).toFixed(f.decimals)} ${f.unit}</strong></div>`).join('')}<div><span>Scenario</span><strong>${isDefault?'Default setup':'Custom setup'}</strong></div><div><span>Recorded</span><strong>${safe(new Date(result.createdAt).toLocaleString())}</strong></div></div><p class="microcopy">Design preview: this is a fixed example, not a calculated prediction for these values.</p><button class="secondary full" id="export-result" style="margin-top:20px">${icon('download',16)} Download result</button>`;$('#export-result').onclick=()=>download('casimir-example-result.json',{...result,units:'mAh',label:'Illustrative UI example — not a computed prediction'});$('#details-dialog').showModal()}
function history(){return `${heading('Your saved results.','Revisit the scenarios you’ve kept for later.')}<section class="panel"><div class="table-heading"><div><h2>Saved scenarios</h2><p>Examples saved on this device.</p></div>${state.history.length?'<button class="secondary small" id="export-history">Download all</button>':''}</div>${state.history.length?`<div class="table-wrap"><table><thead><tr><th scope="col">Scenario</th><th scope="col">Saved</th><th scope="col">Capacity</th><th scope="col">Result</th></tr></thead><tbody>${state.history.map((r,i)=>`<tr><td>Scenario ${String(i+1).padStart(2,'0')}<small class="table-example">Illustrative example</small></td><td>${safe(new Date(r.createdAt).toLocaleString())}</td><td class="numeric">1.840 mAh</td><td><button class="text-button" data-history="${i}">View result ↗</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('history',35)}<h3>Your saved results will live here.</h3><p>Initialize a simulation, then select Save result to keep the example.</p><a class="primary" href="#simulation">Start a simulation ${icon('arrow',15)}</a></div>`}</section><p class="prototype-note">Design preview · Saved values are illustrative examples, stored in this browser.</p>`}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your example download is ready.')}
function render(){state.route=location.hash==='#history'?'history':'simulation';$('#crumb').textContent=state.route==='history'?'Saved results':'Simulation';$('#nav').innerHTML=routes.map(([route,i,name])=>`<a href="#${route}" class="nav-item ${route===state.route?'active':''}" ${route===state.route?'aria-current="page"':''} aria-label="${name}" title="${name}">${icon(i)}<span class="nav-name">${name}</span>${route===state.route?'<span class="nav-arrow">›</span>':''}</a>`).join('');$('#main').innerHTML=state.route==='history'?history():simulation();document.title=`${state.route==='history'?'Saved results':'Simulation'} — Casimir`;document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon,16));bind()}
function bind(){if(state.route==='history'){document.querySelectorAll('[data-history]').forEach(el=>el.onclick=()=>details(state.history[Number(el.dataset.history)]));if($('#export-history'))$('#export-history').onclick=()=>download('casimir-saved-examples.json',{label:'Illustrative UI examples only',units:'mAh',results:state.history});return}
 $('#customize').ontoggle=event=>{state.customOpen=event.currentTarget.open};
 document.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{const f=fields.find(f=>f.key===input.dataset.field);state.inputs[f.key]=input.value===''?'':Number(input.value);if(input.value!=='')$(`#${input.type==='range'?'input':'range'}-${f.key}`).value=input.value;state.result=null;state.error='';$('#form-error').classList.add('hidden');$('#scenario-badge').textContent=changed()?'CUSTOM':'DEFAULT';$('#scenario-name').textContent=changed()?'Custom cell scenario':'Default cell scenario';$('#result-content').innerHTML=resultMarkup();$('#initialize').innerHTML=`${icon('bolt',17)} Initialize simulation <span>→</span>`});
 $('#restore-defaults').onclick=()=>{if(state.running)return;state.inputs=defaults();state.result=null;state.error='';render();toast('Default scenario restored.')};
 $('#simulation-form').onsubmit=initialize;
 if($('#view-details'))$('#view-details').onclick=()=>details(state.result);
 if($('#save-scenario'))$('#save-scenario').onclick=()=>{if(state.history.some(r=>r.createdAt===state.result.createdAt)){toast('This result is already saved.');return}state.history.push({...state.result});storage.set('history',state.history);toast('Result saved. Find it in Saved results.')};
}
async function initialize(event){event.preventDefault();if(state.running)return;state.error='';const invalid=fields.find(f=>state.inputs[f.key]===''||!Number.isFinite(Number(state.inputs[f.key]))||state.inputs[f.key]<f.min||state.inputs[f.key]>f.max||!$(`#input-${f.key}`).validity.valid);if(invalid){state.customOpen=true;state.error=`Enter ${invalid.name.toLowerCase()} between ${invalid.min} and ${invalid.max}.`;render();$(`#input-${invalid.key}`).focus();return}const submitted={...state.inputs};state.running=true;state.result=null;render();try{state.result=await simulationAdapter.initialize(submitted)}catch{state.error='We couldn’t prepare your result. Please try again.'}finally{state.running=false;render();if(state.route==='simulation')$('#result-title').focus({preventScroll:true})}}
document.addEventListener('click',event=>{if(event.target.closest('[data-action="guide"]'))$('#guide-dialog').showModal();const button=event.target.closest('[data-close]');if(button)document.getElementById(button.dataset.close).close()});
$('#guide-start').onclick=()=>$('#guide-dialog').close();$('#guide-dialog').addEventListener('close',()=>storage.set('simple-guide-seen',true));$('#theme-toggle').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');window.addEventListener('hashchange',()=>{render();$('#main').focus();window.scrollTo(0,0)});
setTheme(storage.get('theme','dark')==='light'?'light':'dark');render();if(!storage.get('simple-guide-seen',false))setTimeout(()=>$('#guide-dialog').showModal(),450);


